// @generated helper — vendors the yoyo brand reference image as base64 so the
// Worker can pass it to Grok's image-edits endpoint for character consistency.
// Run:  node scripts/vendor-yoyo-reference.mjs <path-to-yoyo-reference.png>
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const src =
  process.argv[2] ??
  "/Users/yuanhao/vibedev/yoyo-illustrations/yoyo-illustrations/assets/yoyo-reference.png";
const b64 = readFileSync(src).toString("base64");
const out =
  `// @generated by scripts/vendor-yoyo-reference.mjs — DO NOT EDIT BY HAND.\n` +
  `// The yoyo brand reference image, base64-encoded so the Worker can pass it to\n` +
  `// Grok image-edits for character consistency.\n` +
  `export const YOYO_REFERENCE_PNG_BASE64 =\n  "${b64}";\n`;
const dest = join(process.cwd(), "src/lib/vendor/yoyo-reference.generated.ts");
writeFileSync(dest, out);
console.log(`wrote ${dest} (${(b64.length / 1024).toFixed(0)}KB base64)`);
